const fs=require('node:fs'),assert=require('node:assert/strict');
const base='app/src/main/';
const read=p=>fs.readFileSync(base+p,'utf8');
const player=read('java/com/openlocal/office/core/FgMediaPlayer.java');
const lib=read('assets/premium-library.js');
const css=read('assets/style.css');
const archive=read('assets/universal-reader.js');
const main=read('java/com/openlocal/office/MainActivity.java');
assert.match(player,/AspectRatioFrameLayout\.RESIZE_MODE_FIT/);
assert.doesNotMatch(player,/AspectRatioFrameLayout\.RESIZE_MODE_ZOOM/);
assert.match(player,/ScaleGestureDetector/);
assert.match(lib,/deck\.classList\.toggle\('fg-lib-video-grid'/);
assert.match(lib,/visiblePage\.some\(item=>classify\(item\)==='video'\)/);
assert.match(css,/\.fg-lib-grid\.fg-lib-video-grid:not\(\.fg-lib-list\)/);
assert.match(css,/repeat\(2,minmax\(0,1fr\)\)!important/);
assert.match(css,/\.fg-lib-more,\s*\.fg-library-root \.fg-lib-type\{display:none!important\}/);
assert.doesNotMatch(lib,/tile\.append\(more\)/);
assert.match(lib,/tile\.addEventListener\('contextmenu'/);
assert.match(lib,/showFileActions\(item\)/);
assert.doesNotMatch(archive,/ARCHIVE_ORIGINAL_STREAM_TIMEOUT/);
assert.match(archive,/ARCHIVE_IMAGE_STILL_LOADING/);
assert.match(archive,/retryTimer=setTimeout/);
assert.match(archive,/fgRetry=1/);
assert.match(archive,/book-fallback/);
assert.match(main,/active\.responseSampled\(u\.getEncodedPath\(\)\)/);
assert.match(read('assets/epub-reader.js'),/Never erase previously rendered illustrations/);
const gradle=fs.readFileSync('app/build.gradle.kts','utf8');
assert.match(gradle,/versionCode\s*=\s*36/);
assert.match(gradle,/versionName\s*=\s*"0\.15\.14"/);
